const r = await tools.exec_command({cmd:"python - <<'PY'
import json, glob
for p in sorted(glob.glob('/app/plant/*/full-interface.json')):
 d=json.load(open(p)); s=d['scenario']
 print('\n',d['case'],s.get('what'))
 for k in ['load','Tfws','dpfac','dew','iso','drv','chk','wear','rtd','dp_fault','flow_fault','valve','fluid','ua','T0s','valve0','spd0']:
  if k in s:
   v=s[k]
   if isinstance(v,list) and len(v)>16: v=f'{len(v)} entries: first={v[:3]!r}, last={v[-2:]!r}'
   print(' ',k, v)
PY","workdir":"/app","yield_time_ms":10000,"max_output_tokens":6000});
text(r.output);

