class Controller:
    def reset(self):
        self.n=0; self.vi=None
    def step(self,o):
        self.n+=1
        t=(self.n-1)*0.5
        a,b=o['T_sup1'],o['T_sup2']
        if a>105: temp=b
        elif b>105: temp=a
        elif abs(a-b)>0.7: temp=min(a,b)
        else: temp=(a+b)/2
        pos=o['valve_pos']
        target=o['dew']+3.5
        kp=5.0; ki=0.04
        if t<45:
            valve=100.
        else:
            if self.vi is None:
                self.vi=pos-kp*(temp-target)
            e=temp-target
            u=self.vi+kp*e
            if 0<u<100 or (u>=100 and e<0) or (u<=0 and e>0):
                self.vi += ki*e*0.5
            u=self.vi+kp*e
            valve=max(0.,min(100.,u))
        return {'pumpA_cmd':95.,'pumpB_cmd':95.,'pumpC_cmd':95.,'valve_cmd':valve}
